
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_lc_tmlyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_lc_tmlyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.556671586173291e+00, -4.463791354418695e+00, -4.333690834879441e+00, -4.153568788078878e+00, -3.908340549550062e+00, -3.582406363988079e+00, -3.163815167259394e+00, -2.651617592453193e+00, -2.064913426945397e+00, -1.444808551380720e+00, -8.426359728495519e-01, -5.113177513545860e-01, -5.037919623861070e-01, -3.940340660740348e-01, -2.348048491796791e-01, -8.905238248484318e-02, -1.153408765524155e-02, -1.757029664531744e-03, -8.324358735202080e-05, -1.762041501812845e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


